INSERT INTO "FigApparatusRule" (
  "id","packageId","apparatus","levelCode","ruleType","ruleKey","valueJson","sourcePage","verificationStatus"
)
SELECT
  "beamRules"."id","beamRules"."packageId",'BALANCE_BEAM',"beamRules"."levelCode",
  'PRESCRIBED_ROUTINE','beam_routine',"beamRules"."valueJson","beamRules"."sourcePage",'VERIFIED'
FROM "beamRules"
WHERE EXISTS (SELECT 1 FROM "RulesetPackage" package WHERE package."id" = "beamRules"."packageId")
AND NOT EXISTS (
  SELECT 1 FROM "FigApparatusRule" existing
  WHERE existing."packageId" = "beamRules"."packageId"
    AND existing."apparatus" = 'BALANCE_BEAM'
    AND existing."levelCode" = "beamRules"."levelCode"
    AND existing."ruleKey" = 'beam_routine'
);
